"""Interactive full-universe Step 2 report, with local chart and trade data."""
import csv
import json
import statistics
from pathlib import Path

from plotly.offline import get_plotlyjs

OUTPUT = Path(__file__).resolve().parents[3] / "docs/temp/step2"
SCOPES = ["Priority assets", "Whole universe", "Watchlist ETFs & crypto", "Bonds", "Major companies", "Other instruments"]


def aggregate(result):
    fields = result["metadata"]["fields"]
    grid = []
    for scope in SCOPES:
        instruments = [s for s in result["instruments"] if scope == "Whole universe"
                       or scope == "Priority assets" and s["priority"]
                       or scope == "Watchlist ETFs & crypto" and s["group"] == "Watchlist"
                       or scope == s["group"]]
        for mode in result["metadata"]["modes"]:
            for entry in result["metadata"]["entries"]:
                for exit_len in result["metadata"]["exits"]:
                    rows = [dict(zip(fields, next(r for r in s["rows"] if r[:3] == [entry, exit_len, mode]))) for s in instruments]
                    eligible = [r for r in rows if r["common_days"] >= 2 * 365.25]
                    scores = [-1.0 if r["exhausted"] else r["common_cagr"] for r in eligible]
                    assert all(v is not None for v in scores)
                    median = lambda values: statistics.median(values) if values else None
                    grid.append({"scope": scope, "mode": mode, "entry": entry, "exit": exit_len,
                                 "instruments": len(rows), "eligible": len(eligible),
                                 "positive_full": sum(r["net"] > 0 and not r["exhausted"] for r in rows),
                                 "positive_common": sum(r["common_net"] > 0 and not r["exhausted"] for r in eligible),
                                 "median_cagr": median(scores),
                                 "median_drawdown": median(max(-1, r["common_drawdown"]) for r in eligible),
                                 "median_full_return": median(r["net"] for r in rows),
                                 "thin_trade_samples": sum(r["common_trades"] < 5 for r in eligible),
                                 "exhausted": sum(r["exhausted"] for r in rows),
                                 "channel_exit_share": sum(r["channel_exits"] for r in rows) / max(1, sum(r["trades"] for r in rows)),
                                 "closed_trades": sum(r["trades"] for r in rows)})
    entries, exits = result["metadata"]["entries"], result["metadata"]["exits"]
    for g in grid:
        ei, xi = entries.index(g["entry"]), exits.index(g["exit"])
        neighbors = [r["median_cagr"] for r in grid if r["scope"] == g["scope"] and r["mode"] == g["mode"]
                     and abs(entries.index(r["entry"]) - ei) + abs(exits.index(r["exit"]) - xi) <= 1
                     and r["median_cagr"] is not None]
        g["neighbor_median"] = statistics.median(neighbors) if neighbors else None
    return grid


def main():
    result = json.loads((OUTPUT / "results.json").read_text(encoding="utf-8"))
    assert not result["metadata"]["partial"], "Publish the report only after the full run completes"
    grid = aggregate(result)
    findings = {scope: {mode: sorted([r for r in grid if r["scope"] == scope and r["mode"] == mode],
                                    key=lambda r: r["median_cagr"] if r["median_cagr"] is not None else -2, reverse=True)[:3]
                       for mode in result["metadata"]["modes"]} for scope in SCOPES}
    (OUTPUT / "findings.json").write_text(json.dumps(findings, indent=2, allow_nan=False), encoding="utf-8")
    with (OUTPUT / "grid.csv").open("w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=list(grid[0]))
        writer.writeheader()
        writer.writerows(grid)
    result["grid"] = grid
    payload = json.dumps(result, allow_nan=False, separators=(",", ":")).replace("<", "\\u003c")
    (OUTPUT / "report.html").write_text(TEMPLATE.replace("__PLOTLY__", get_plotlyjs()).replace("__DATA__", payload), encoding="utf-8")
    print(json.dumps({"report": str(OUTPUT / "report.html"), "priority": findings["Priority assets"],
                      "whole_universe": findings["Whole universe"]}), flush=True)


